/* selectMessage - Lee JiSeob */
SELECT
MSSAGE_ID, MSSAGE_KLANG_CN, MSSAGE_ENL_CN, MSSAGE_CHNLNG_CN, MSSAGE_JPLNG_CN, USE_YN, FRST_RGTR_ID, TO_CHAR(FRST_REG_DT, 'YYYY-MM-DD HH24:MI') AS FRST_REG_DT, LAST_MDFR_ID, TO_CHAR(LAST_MDFCN_DT, 'YYYY-MM-DD HH24:MI') AS LAST_MDFCN_DT
FROM SAB810 /* 메시지 */
WHERE USE_YN IS NULL OR USE_YN = 'Y' AND MSSAGE_ID = #{MSSAGE_ID}


/* checkExistsMessage - Lee JiSeob */

SELECT 

	COUNT(*) AS EXISTS_COUNT

FROM SAB810 /* 메시지 */

WHERE MSSAGE_ID = #{MSSAGE_ID}

mapper.update:
/* updateMessage - Lee JiSeob */
UPDATE SAB810 /* 메시지 */ SET MSSAGE_KLANG_CN = #{mssageKlangCn}, MSSAGE_ENL_CN = #{mssageEnlCn}, MSSAGE_CHNLNG_CN = #{mssageChnlngCn}, MSSAGE_JPLNG_CN = #{mssageJplngCn}, USE_YN = #{useYn}, LAST_MDFR_ID = #{USER_ID}, LAST_MDFCN_DT = SYSDATE
WHERE MSSAGE_ID = #{mssageId}
